-- Hyprland 0.57. Each part lives beside this file in ~/.config/hypr/ and is
-- loaded as hypr.<name>. The original example config is hyprland.lua.autogenerated.

package.path = os.getenv("HOME") .. "/.config/?.lua;" .. package.path

-- Forget the modules a previous load cached, so a reload picks up edits.
for name in pairs(package.loaded) do
  if name:sub(1, 5) == "hypr." then
    package.loaded[name] = nil
  end
end

require("hypr.envs")
require("hypr.monitors")
require("hypr.input")
require("hypr.looknfeel")
require("hypr.rules")
require("hypr.bindings")
require("hypr.autostart")
